import time

articles = [
    {"id": "a1", "text": "Company X announces new product line.", "published_at": time.time() - 300},
    {"id": "a2", "text": "Company X product line was first teased.", "published_at": time.time() - 86400},
]

def time_decay_score(article, half_life_seconds=3600):
    # more recent articles score higher via exponential decay
    age = time.time() - article["published_at"]
    return 0.5 ** (age / half_life_seconds)

def retrieve_with_recency(query, articles):
    matches = [a for a in articles if any(w in a["text"].lower() for w in query.lower().split())]
    return sorted(matches, key=time_decay_score, reverse=True)

def generate_with_timestamp(top_article):
    # the answer states how long ago the source was published
    minutes_ago = int((time.time() - top_article["published_at"]) / 60)
    return f"{top_article['text']} (published approximately {minutes_ago} minutes ago)"

results = retrieve_with_recency("company product", articles)
print("Real-time news assistant example:")
print(generate_with_timestamp(results[0]))
